using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NpcFreightTests
{
    static readonly EntityId Home=new("site:castle"),Source=new("site:kofu"),Head=new("person:nobunaga"),Carrier=new("created:freight-carrier");
    internal static WorldSession Start(bool willing=true)
    {
        var basis=NewGameWorld.Scenario(HistoricalStartCatalog.Current);
        var officers=NewGameWorld.Normalize([NewGameWorldTests.Officer(Carrier.Value,StartTemplate.Retainer,lord:Head.Value)]);
        var request=new WorldSetupRequest(officers,[]);var preview=NewGameSetup.Preview(basis,request);Assert.True(preview.IsEligible(),string.Join(',',preview.Errors));
        var scenario=NewGameSetup.Confirm(basis,request,preview);
        var w=NewGameWorld.Create(scenario,officers,Head.Value,1,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:NpcFreight.Policy);
        if(!willing)w.Characters=w.Characters.Select(c=>c.Id==Carrier?c with{WillObey=false}:c).ToArray();
        return new(w);
    }
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long target){while(s.Seconds<target){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(target,100000);Assert.True(s.Seconds>old);}}
    static CommandResult Assign(WorldSession s,string id="request:delegate-freight",long advance=200,long amount=10,string? commodity="wood",EntityId? carrier=null)=>s.ManageHouseFreight(new(new(id),HouseFreightAction.Dispatch,Home:Home,Source:Source,Commodity:commodity,Quantity:amount,Advance:advance){Carrier=carrier??Carrier},s.PlayerControl,s.Revision);
    static HouseFreightJob Job(WorldSession s)=>HouseLogistics.FreightJobs(s.DiagnosticSnapshot(),s.Seconds,s.Revision+1).Single();
    [Fact]public void LocalHeadCanDelegateWithoutMovingOrSpendingPrivateMoney(){var s=Start();Assert.Contains(Carrier,NpcFreight.Candidates(s.DiagnosticSnapshot(),Home));Good(Assign(s));Assert.Equal(300,s.HouseTreasuryView()!.HouseCash);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Head));Assert.Empty(s.HouseFreightView()!.Jobs);Advance(s,62);Assert.Contains(s.DiagnosticSnapshot().Branches!.Journeys,j=>j.Actor==Carrier);Assert.Equal(Home,s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Head).Site);}
    [Fact]public void ActualRetainerRoundTripTransfersStockCashAndReceiptOnce(){var s=Start();Good(Assign(s));Advance(s,62);var outbound=s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier);Advance(s,outbound.Legs[^1].EndAt+120);Assert.Equal(10,Job(s).Cargo);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Carrier).Legs[^1].EndAt+120);Assert.Equal(HouseFreightPhase.Completed,Job(s).Phase);Assert.Equal(30,s.HouseTreasuryView()!.Materials.Wood);Assert.Equal(440,s.HouseTreasuryView()!.HouseCash);Assert.NotNull(s.DelegatedFreightView().Single().Receipt);var before=ContractJson.Write(s.DiagnosticSnapshot());Advance(s,s.Seconds+600);Assert.Equal(30,s.HouseTreasuryView()!.Materials.Wood);Assert.Equal(440,s.HouseTreasuryView()!.HouseCash);Good(Assign(s,"request:delegate-again",advance:100));Assert.Equal(2,s.DiagnosticSnapshot().HouseFreight!.Entries.Count(e=>e.Terms!=null));}
    [Fact]public void SourcePriceShortageReturnsAllAdvanceWithoutCargo(){var s=Start();Good(Assign(s,advance:1));Advance(s,62);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier).Legs[^1].EndAt+120);Assert.Equal(0,Job(s).Cargo);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Carrier).Legs[^1].EndAt+120);Assert.Equal(HouseFreightPhase.Returned,Job(s).Phase);Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);Assert.Equal(20,s.HouseTreasuryView()!.Materials.Wood);}
    [Fact]public void RemoteViewShowsNoLiveCargoCashOrPrice(){var s=Start();Good(Assign(s));Advance(s,62);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier).Legs[^1].EndAt+120);Assert.Equal(10,Job(s).Cargo);var text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DelegatedFreightView()));Assert.DoesNotContain("UnitPrice",text);Assert.DoesNotContain("Cash",text);Assert.DoesNotContain("Cargo",text);Assert.DoesNotContain("Carrying",text);Assert.Null(s.DelegatedFreightView().Single().Receipt);}
    [Fact]public void CannotManuallyWithdrawOrReceiveRemoteRetainerFreight(){var s=Start();Good(Assign(s));Advance(s,62);foreach(var action in new[]{HouseFreightAction.Buy,HouseFreightAction.Withdraw,HouseFreightAction.Receive}){var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:remote/"+action),action,new("request:delegate-freight")),Head,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}}
    [Fact]public void BusyCarrierAndBudgetCannotBeAssignedTwice(){var s=Start();Good(Assign(s));var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Assign(s,"request:second").Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.DoesNotContain(Carrier,NpcFreight.Candidates(s.DiagnosticSnapshot(),Home));}
    [Fact]public void UnwillingOrNonRetainerCannotReceiveEntrustedCash(){var s=Start(false);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Assign(s).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));var other=Start();Assert.Equal(ResultCode.NotAvailable,Assign(other,carrier:new("person:ujiyasu")).Code);}
    [Fact]public void OriginalV12StillOmitsCarrierAndRetainsBytes(){var w=NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],Head.Value,1,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:MilitaryEconomy.Policy);var b=ContractJson.Write(w);Assert.DoesNotContain("Carrier\":null",System.Text.Encoding.UTF8.GetString(b));Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));Assert.Empty(NpcFreight.Candidates(w,Home));}

    [Theory][InlineData(null,10)][InlineData("weapons",2)]public void RiceAndWeaponsUseSameRealCustody(string? kind,long quantity){var s=Start();Good(Assign(s,commodity:kind,amount:quantity));Advance(s,62);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier).Legs[^1].EndAt+120);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Carrier).Legs[^1].EndAt+120);Assert.Equal(HouseFreightPhase.Completed,Job(s).Phase);Assert.Equal(kind==null?3010:3000,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(kind=="weapons"?12:10,s.HouseTreasuryView()!.Materials.Weapons);}
    [Fact]public void RepeatedConflictAndStaleAgreementCannotDuplicateAdvance(){var s=Start();long rev=s.Revision;Good(Assign(s));Assert.Equal(ResultCode.AlreadyAccepted,Assign(s).Code);Assert.Equal(ResultCode.IdPayloadConflict,Assign(s,advance:100).Code);Assert.Equal(ResultCode.StateChanged,s.ManageHouseFreight(new(new("request:stale-npc"),HouseFreightAction.Dispatch,Home:Home,Source:Source,Commodity:"wood",Quantity:1,Advance:1){Carrier=Carrier},Head,rev).Code);Assert.Equal(300,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void ExistingFreightDoesNotBlockPlayersSeparatePersonalTrade(){var s=Start();Good(Assign(s,advance:100));Good(s.TradeRice(new(new("request:pc-private-while-retainer-away"),TradeAction.Quote,Home,Destination:Source,Amount:1){Commodity="wood"},Head,s.Revision));Assert.Equal(100,s.DiagnosticSnapshot().HouseFreight!.Entries.Single().Terms!.Advance);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedCarrierOwnershipAndDispatchCannotLoad(int change){var s=Start();Good(Assign(s));var w=s.DiagnosticSnapshot();var e=w.HouseFreight!.Entries.Single();w.HouseFreight=w.HouseFreight with{Entries=[change==0?e with{Actor=Head}:change==1?e with{Input=e.Input with{Carrier=new("person:ujiyasu")}}:e with{Terms=e.Terms! with{Advance=0}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void CannotSendBusyCarrierToUnrelatedDestination(){var s=Start();Good(Assign(s));var i=TravelWorld.Move(s.DiagnosticSnapshot(),"request:wrong-carrier-trip","kyoto") with{Actor=Carrier,Executor=Carrier};Assert.Equal(ResultCode.InvalidInput,s.Submit(i,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void RealGenerationSaveRestoresCargoTravelKnowledgeAndFuture(int phase)
    {
        var a=Start();Good(Assign(a,advance:phase==4?1:200));if(phase>0)Advance(a,62);if(phase>=2){Advance(a,a.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier).Legs[^1].EndAt+120);if(phase==3)Advance(a,a.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Carrier).Legs[^1].EndAt+120);}
        a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"npc-freight-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"freight",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("freight"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.DelegatedFreightView()),ContractJson.Write(b.DelegatedFreightView()));
        var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"npc-freight-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"npc-freight-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}
        foreach(var q in new[]{a,b}){if(phase==0)Advance(q,62);if(phase<2)Advance(q,q.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier).Legs[^1].EndAt+120);if(phase!=3)Advance(q,q.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Carrier).Legs[^1].EndAt+120);Advance(q,q.Seconds+120);}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(phase==4?HouseFreightPhase.Returned:HouseFreightPhase.Completed,Job(a).Phase);
    }

    [Fact]public void LocalWithdrawalRequiresActualMeetingAndReturnsMoneyPhysically(){var s=Start();Good(Assign(s));Assert.True(NpcFreight.CanRecallAtMeeting(s.DiagnosticSnapshot(),new("request:delegate-freight")));Good(s.ManageHouseFreight(new(new("request:local-recall"),HouseFreightAction.Withdraw,new("request:delegate-freight")),Head,s.Revision));Assert.Equal(300,s.HouseTreasuryView()!.HouseCash);Advance(s,62);Assert.Equal(HouseFreightPhase.Returned,Job(s).Phase);Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);Assert.Empty(s.DiagnosticSnapshot().Branches!.Journeys);}
    [Fact]public void ExpiryAtHomeDoesNotEraseAdvanceOrRequireTeleport(){var s=Start();Good(Assign(s));var w=s.DiagnosticSnapshot();w.ElapsedSeconds=31*86400;/* Check derived phase only; a full forged world is not loaded. */Assert.Equal(HouseFreightPhase.ReturnRequired,HouseLogistics.FreightJobs(w,w.ElapsedSeconds,w.CommitSequence+1).Single().Phase);Assert.Equal(200,HouseLogistics.FreightJobs(w,w.ElapsedSeconds,w.CommitSequence+1).Single().Cash);}

    [Fact]public void UnknownRoadClosuresDoNotChangeKnownAgreementOrRevealHiddenStock(){var a=Start();var w=Start().DiagnosticSnapshot();var blocked=BranchRoutes.GraphEdges(w).Select(e=>e.Id).ToArray();w.Branches=w.Branches! with{BlockedEdges=blocked};w.Couriers=w.Couriers! with{InitialBlocked=blocked};var b=new WorldSession(w);Good(Assign(a));Good(Assign(b));Assert.Equal(ContractJson.Write(a.DelegatedFreightView()),ContractJson.Write(b.DelegatedFreightView()));Advance(b,240);Assert.Equal(200,Job(b).Cash);Assert.Equal(0,Job(b).Cargo);Assert.NotEqual(Source,b.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Carrier).Site);Assert.DoesNotContain(b.DiagnosticSnapshot().HouseFreight!.Entries,e=>e.Input.Action==HouseFreightAction.Buy);}
    [Fact]public void EveryDelegatedJourneyUsesLandOnly(){var s=Start();Good(Assign(s));Advance(s,62);Assert.All(s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier).Legs,l=>Assert.False(NationalRoutes.Sea(l.Edge)));}
    [Fact]public void CannotDelegateToSelfOrForgeAnotherCaller(){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Assign(s,carrier:Head).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:impersonation"),HouseFreightAction.Dispatch,Home:Home,Source:Source,Commodity:"wood",Quantity:1,Advance:1){Carrier=Carrier},Carrier,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}

    [Fact]public void NormalCampaignEntryKeepsAllPoliciesAndPermitsDelegatedTrip(){var seed=Start().DiagnosticSnapshot().NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"npc-freight-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(seed.Start,seed.Registered,Head.Value,1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,NpcFreight.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Good(Assign(s));Advance(s,62);Assert.Contains(s.DiagnosticSnapshot().Branches!.Journeys,j=>j.Actor==Carrier);Assert.True(MilitaryEconomy.Enabled(s.DiagnosticSnapshot()));Assert.NotNull(s.DiagnosticSnapshot().MilitaryEconomy);Assert.NotNull(s.HouseTreasuryView());Assert.NotNull(s.StewardshipView());}
    [Fact]public void KnownReturnedReceiptRemainsKnownAfterHeadLeavesHome(){var s=Start();Good(Assign(s));Advance(s,62);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier).Legs[^1].EndAt+120);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Carrier).Legs[^1].EndAt+120);var receipt=s.DelegatedFreightView().Single().Receipt;Assert.NotNull(receipt);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:leave-after-receipt","fork"),s.Revision));Advance(s,s.Seconds+2);Assert.Equal(receipt,s.DelegatedFreightView().Single().Receipt);}
}
